const riskPriority = {
    Low: 1,
    Medium: 2,
    High: 3,
    Critical: 4,
};

function formatDate(value) {
    if (!value) {
        return 'Not set';
    }

    const [year, month, day] = value.split('-').map(Number);

    // Local date construction prevents UTC date shifts.
    return new Intl.DateTimeFormat('en-PH', {
        month: 'short',
        day: '2-digit',
        year: 'numeric',
    }).format(new Date(year, month - 1, day));
}

function riskBadge(risk) {
    const className = risk.toLowerCase();

    return `
        <span class="prediction-risk prediction-risk-${className}">
            ${escapeHtml(risk)}
        </span>
    `;
}

class SpoilagePredictionUI {
    constructor(tableElement) {
        this.tableElement = tableElement;
        this.assessments = sampleAssessments;
        this.modal = Modal.getOrCreateInstance(
            document.getElementById('predictionViewModal'),
        );

        this.renderSummary();
        this.initializeTable();
        this.mountTableScroller();
        this.bindEvents();
    }

    renderSummary() {
        const countRisk = (risk) =>
            this.assessments.filter((item) => item.risk === risk).length;

        document.getElementById('predictionTotal').textContent =
            this.assessments.length;

        document.getElementById('predictionLow').textContent =
            countRisk('Low');

        document.getElementById('predictionMedium').textContent =
            countRisk('Medium');

        document.getElementById('predictionUrgent').textContent =
            countRisk('High') + countRisk('Critical');
    }

    initializeTable() {
        this.table = new DataTable(this.tableElement, {
            data: this.assessments,
            autoWidth: false,
            pageLength: 5,
            lengthMenu: [5, 10, 25, 50],
            order: [
                [4, 'desc'],
                [0, 'asc'],
            ],
            layout: {
                topStart: null,
                topEnd: null,
                bottomStart: 'info',
                bottomEnd: 'paging',
            },
            language: {
                emptyTable: 'No batch assessments available.',
                zeroRecords: 'No matching batches found.',
                info: 'Showing _START_ to _END_ of _TOTAL_ entries',
                infoEmpty: 'Showing 0 to 0 of 0 entries',
                infoFiltered: '(filtered from _MAX_ total entries)',
                paginate: {
                    first: '«',
                    previous: '‹',
                    next: '›',
                    last: '»',
                },
            },
            columns: [
                {
                    data: 'batch',
                    render: (data, type) =>
                        type === 'display'
                            ? `<span class="prediction-batch-code">${escapeHtml(data)}</span>`
                            : data,
                },
                {
                    data: 'flowerName',
                    render: (data, type, row) => {
                        if (type !== 'display') {
                            return `${data} ${row.flowerCode} ${row.category}`;
                        }

                        return `
                            <div class="prediction-flower">
                                <span class="prediction-flower-icon">
                                    <i class="bi bi-flower1" aria-hidden="true"></i>
                                </span>
                                <div>
                                    <strong>${escapeHtml(data)}</strong>
                                    <small>
                                        ${escapeHtml(row.flowerCode)}
                                        · ${escapeHtml(row.category)}
                                    </small>
                                </div>
                            </div>
                        `;
                    },
                },
                {
                    data: 'remaining',
                    render: (data, type) =>
                        type === 'display'
                            ? Number(data).toLocaleString('en-PH')
                            : data,
                },
                {
                    data: 'expiryDate',
                    render: (data, type) => {
                        if (type === 'sort' || type === 'type') {
                            return data || '';
                        }

                        return type === 'display'
                            ? escapeHtml(formatDate(data))
                            : data || 'Not set';
                    },
                },
                {
                    data: 'risk',
                    render: (data, type) => {
                        if (type === 'sort' || type === 'type') {
                            return riskPriority[data];
                        }

                        return type === 'display' ? riskBadge(data) : data;
                    },
                },
                {
                    data: 'recommendation',
                    render: (data, type) =>
                        type === 'display'
                            ? `<p class="prediction-recommendation">${escapeHtml(data)}</p>`
                            : data,
                },
                {
                    data: null,
                    orderable: false,
                    searchable: false,
                    render: (_data, type, row) => {
                        if (type !== 'display') {
                            return '';
                        }

                        return `
                            <button
                                type="button"
                                class="prediction-view-btn"
                                data-view-prediction="${escapeHtml(row.batch)}"
                                aria-label="View assessment for ${escapeHtml(row.batch)}"
                                title="View assessment"
                            >
                                <i class="bi bi-eye" aria-hidden="true"></i>
                            </button>
                        `;
                    },
                },
            ],
        });
    }

    mountTableScroller() {
        const scroller = document.createElement('div');

        scroller.className = 'prediction-table-scroll';
        scroller.tabIndex = 0;
        scroller.setAttribute('role', 'region');
        scroller.setAttribute(
            'aria-label',
            'Batch risk assessments. Scroll horizontally to see all columns.',
        );

        // Wrap only the table, keeping results and pagination outside.
        this.tableElement.before(scroller);
        scroller.append(this.tableElement);
    }

    bindEvents() {
        document
            .getElementById('predictionSearch')
            .addEventListener('input', (event) => {
                this.table.search(event.target.value).draw();
            });

        document
            .getElementById('predictionPageLength')
            .addEventListener('change', (event) => {
                this.table.page.len(Number(event.target.value)).draw();
            });

        this.tableElement.addEventListener('click', (event) => {
            const button = event.target.closest('[data-view-prediction]');

            if (!button) {
                return;
            }

            this.showAssessment(button.dataset.viewPrediction);
        });
    }

    showAssessment(batchCode) {
        const item = this.assessments.find(
            (assessment) => assessment.batch === batchCode,
        );

        if (!item) {
            return;
        }

        document.getElementById('predictionViewModalLabel').textContent =
            `Risk Assessment — ${item.batch}`;

        const renderList = (items) =>
            items.map((text) => `<li>${escapeHtml(text)}</li>`).join('');

        document.getElementById('predictionViewContent').innerHTML = `
            <div class="prediction-detail-heading">
                <div>
                    <h3>${escapeHtml(item.flowerName)}</h3>
                    <p>
                        ${escapeHtml(item.batch)}
                        · ${escapeHtml(item.flowerCode)}
                        · ${escapeHtml(item.category)}
                    </p>
                </div>
                ${riskBadge(item.risk)}
            </div>

            <dl class="prediction-detail-grid">
                <div>
                    <dt>Remaining Quantity</dt>
                    <dd>${item.remaining.toLocaleString('en-PH')} stems</dd>
                </div>
                <div>
                    <dt>Received Date</dt>
                    <dd>${escapeHtml(formatDate(item.receivedDate))}</dd>
                </div>
                <div>
                    <dt>Harvest Date</dt>
                    <dd>${escapeHtml(formatDate(item.harvestDate))}</dd>
                </div>
                <div>
                    <dt>Freshness / Expiry</dt>
                    <dd>${escapeHtml(formatDate(item.expiryDate))}</dd>
                </div>
                <div>
                    <dt>Sample Assessment Date</dt>
                    <dd>${escapeHtml(formatDate(SAMPLE_ASSESSMENT_DATE))}</dd>
                </div>
                <div>
                    <dt>Assessment Source</dt>
                    <dd>UI sample · No ML model connected</dd>
                </div>
            </dl>

            <div class="prediction-detail-section">
                <h4>Sample Indicators</h4>
                <ul>${renderList(item.indicators)}</ul>
            </div>

            <div class="prediction-detail-section">
                <h4>Recommended Actions</h4>
                <ul>${renderList(item.actions)}</ul>
            </div>

            <p class="prediction-detail-note">
                Risk level is advisory and does not confirm spoilage.
                This screen does not deduct stock or change batch status.
                Record actual spoilage in Inventory Management after inspection.
            </p>
        `;

        this.modal.show();
    }
}

function initializeSpoilagePrediction() {
    const table = document.getElementById('predictionTable');

    if (!table || DataTable.isDataTable(table)) {
        return;
    }

    new SpoilagePredictionUI(table);
}

if (document.readyState === 'loading') {
    document.addEventListener(
        'DOMContentLoaded',
        initializeSpoilagePrediction,
        { once: true },
    );
} else {
    initializeSpoilagePrediction();
}